const pending = new Map();
const asynchronousFeed = createProgressFeed({
  decode: packet => new Promise(resolve => pending.set(packet.id, resolve)),
});
const history = [];
const shown = [];
const asyncWorkspace = createTransferWorkspace({
  transport: () => {}, onCancel: () => {}, record: () => {}, showQueued: () => {},
  recordProgress: value => history.push(value.frame.id),
  showProgress: value => shown.push(value.frame.id),
});
